	private static void replayBindingRecipe(boolean missingProducer) {
		var vf = SimpleValueFactory.getInstance();
		var expression = new Join(new StatementPattern(Var.of("s"), Var.of("p", vf.createIRI("urn:p")), Var.of("o")),
				new StatementPattern(Var.of("o"), Var.of("q", vf.createIRI("urn:q")), Var.of("z")));
		PackedQuery query = PackedQueryCodec.encodeForPlanning(expression);
		int root = query.rootRelId();
		int leftRelation = query.relChild(root, 0);
		int rightRelation = query.relChild(root, 1);
		int count = query.relationCount();
		try (EventSourcingPackedCostSession recording = new EventSourcingPackedCostSession(
				new BindingSession(100, missingProducer));
				PackedMemo memo = new PackedMemo(query, query.symbolCount(), count, count, 4, count, count * 2)) {
			PackedCostContext context = new PackedCostContext();
			PackedCostEstimate left = new PackedCostEstimate();
			PackedCostEstimate right = new PackedCostEstimate();
			recording.estimateLeaf(leftRelation, context, left);
			recording.estimateLeaf(rightRelation, context, right);
			PackedCostEstimate output = new PackedCostEstimate();
			output.copyCandidateFrom(right);
			context.reset(new int[] { leftRelation }, 0, 1, left.outputRows(),
					missingProducer ? Integer.MAX_VALUE : left.evidenceStateId());
			recording.appendFactor(rightRelation, context, output);
			int property = memo.anyPropertyId();
			int[] childWinners = new int[2];
			int[] childGroups = new int[2];
			int[] childRelations = { leftRelation, rightRelation };
			PackedCostEstimate[] prices = { left, right };
			for (int child = 0; child < 2; child++) {
				int relation = childRelations[child];
				int group = memo.logicalGroupId(relation);
				childGroups[child] = group;
				int physical = memo.addPhysicalAlternative(group, query.relOperator(relation),
						query.relPayload(relation),
						property, 7, new int[0], 0, 0);
				PackedCostEstimate price = prices[child];
				int metadata = memo.addPhysicalMetadata(price, price.outputRows(), price.workRows());
				childWinners[child] = memo.offerWinnerWithMetadata(group, property, 0, 0, 0, physical, metadata,
						0.0d, price.workRows(), price.workRows(), new int[0], 0, 0);
			}
			int group = memo.logicalGroupId(root);
			int physical = memo.addPhysicalAlternative(group, query.relOperator(root), query.relPayload(root), property,
					PackedJoinEnumerator.JOIN_IMPLEMENTATION, childGroups, 0, 2);
			int metadata = memo.addPhysicalMetadata(output, output.outputRows(), output.workRows());
			int winner = memo.offerWinnerWithMetadata(group, property, 0, 0, 0, physical, metadata,
					0.0d, output.workRows(), output.workRows(), childWinners, 0, 2);
			PackedPlanRecipe recipe = memo.extractPlanRecipe(winner, new PackedDependentPlans(), recording);
			assertEquals(0, recipe.frontierEvidenceBundle().stateCount());
			BindingSession fresh = new BindingSession(1000);
			if (missingProducer) {
				IllegalStateException rejected = assertThrows(IllegalStateException.class,
						() -> PackedCostingReplay.replay(PackedPlanValidationRequest.detachedContinuation(
								new PackedQueryView(query), recipe), fresh));
				assertTrue(rejected.getMessage().contains("before its originating event"));
				assertEquals(0, fresh.appendCalls, "the actual dependent provider must not run");
				return;
			}
			PackedCostingReplay.Result replay = PackedCostingReplay.replay(
					PackedPlanValidationRequest.detachedContinuation(new PackedQueryView(query), recipe), fresh);
			PackedCostEstimate restored = new PackedCostEstimate();
			replay.copyEventEstimate(replay.eventCount(), restored);
			assertEquals(output.outputRows(), restored.outputRows());
			assertTrue(restored.evidenceStateId() > 1000, "a fresh current-session state replaced the cached handle");
			assertEquals(0, replay.currentEvidence().stateCount());
			assertEquals(0, fresh.exactContinuationIdentity(restored));
		}
	}

	@Test
	void legacyNullMapUsesOnlyAuthenticatedBundleCountAndValidatesEveryReferenceRole() {
		for (int role = 0; role < 9; role++) {
			PackedCostingTraceArena arena = new PackedCostingTraceArena();
			PackedCostContext context = new PackedCostContext();
			PackedCostContext source = new PackedCostContext();
			PackedCostEstimate input = new PackedCostEstimate();
			PackedCostEstimate output = new PackedCostEstimate();
			int sparse = Integer.MAX_VALUE;
			switch (role) {
			case 0 -> context.reset(new int[0], 0, 0, 1.0d, sparse);
			case 1 -> context.setOperatorInputs(1.0d, 1.0d, sparse, 0);
			case 2 -> context.setOperatorInputs(1.0d, 1.0d, 0, sparse);
			case 3 -> source.reset(new int[0], 0, 0, 1.0d, sparse);
			case 4 -> source.setOperatorInputs(1.0d, 1.0d, sparse, 0);
			case 5 -> source.setOperatorInputs(1.0d, 1.0d, 0, sparse);
			case 6 -> output.setEvidenceStateId(sparse);
			case 7 -> input.setEvidenceStateId(sparse);
			case 8 -> {
			}
			default -> throw new AssertionError(role);
			}
			arena.append(PackedCostingPhase.LEAF, 1, source, role == 8 ? sparse : 0, context,
					input, output, 1.0d);
			PackedCostingTrace legacy = arena.snapshot();
			IllegalStateException rejected = assertThrows(IllegalStateException.class,
					() -> legacy.stateHandleCount(1), "invalid legacy role " + role);
			assertTrue(rejected.getMessage().contains("invalid state reference"));
		}
		PackedCostingTraceArena arena = new PackedCostingTraceArena();
		PackedCostEstimate output = new PackedCostEstimate();
		output.setEvidenceStateId(2);
		PackedCostContext context = new PackedCostContext();
		arena.append(PackedCostingPhase.LEAF, 1, context, 0, context, new PackedCostEstimate(), output, 1.0d);
		assertEquals(3, arena.snapshot().stateHandleCount(3), "legacy storage bound belongs to the bundle");
		assertThrows(IllegalStateException.class, () -> arena.snapshot().stateHandleCount(0),
				"an absent producer inventory cannot authenticate a legacy raw state");
	}

	@Test
	void unavailablePhysicalPriceSurvivesCandidateCopyAndPhysicalReplacementWithoutStaleObjective() {
		PackedCostEstimate declared = unknownPriceDeclaration();
		PackedCostEstimate copied = new PackedCostEstimate();
		copied.setObjectiveInterval(100.0d, 101.0d, 102.0d);
		copied.copyCandidateFrom(declared);
		assertUnavailablePrice(copied, 17.0d);
		assertEquals(29.0d, copied.plannedDoubleMetrics().get("producerMetric"));
		PackedCostEstimate replacement = new PackedCostEstimate();
		replacement.setRows(101.0d, 103.0d);
		replacement.setObjectiveInterval(100.0d, 101.0d, 102.0d);
		replacement.putPlannedDoubleMetric("callerMetric", 37.0d);
		replacement.replacePhysicalCost(declared, true);
		assertUnavailablePrice(replacement, 101.0d);
		assertEquals(37.0d, replacement.plannedDoubleMetrics().get("callerMetric"));
		replacement.setContextualOutputRowsPreservingPhysicalCost(17.0d);
		assertUnavailablePrice(replacement, 17.0d);
		assertTrue(replacement.hasContextualOutputRows());
	}

	@Test
	void traceKeepsUnavailablePriceSeparateFromTheExistingConservativeOrderingScore() {
		PackedCostEstimate declaration = unknownPriceDeclaration();
		PackedCostSession provider = new PackedCostSession() {
			@Override
			public void estimateLeaf(int relation, PackedCostContext context, PackedCostEstimate output) {
				output.copyCandidateFrom(declaration);
			}

			@Override
			public void appendFactor(int relation, PackedCostContext context, PackedCostEstimate output) {
			}

			@Override
			public void refineOperator(int relation, PackedCostContext context, PackedCostEstimate output) {
			}
		};
		try (EventSourcingPackedCostSession recording = new EventSourcingPackedCostSession(provider)) {
			PackedCostEstimate output = new PackedCostEstimate();
			output.copyCandidateFrom(declaration);
			recording.estimateLeaf(1, new PackedCostContext(), output);
			assertUnavailablePrice(output, 17.0d);
			assertEquals(Double.MAX_VALUE, recording.objectiveScore(output),
					"the unchanged provider boundary conservatively orders unknown costs");
			PackedCostingTrace trace = recording.snapshotTrace();
			assertTrue(Double.isNaN(trace.workRows(1)));
			assertTrue(Double.isNaN(trace.sequentialRows(1)));
			assertEquals(2.0d, trace.randomSeeks(1));
			assertEquals(Double.MAX_VALUE, trace.objectiveCost(1), "ordering score is not a resource counter");
			PackedCostEstimate restored = new PackedCostEstimate();
			restored.setObjectiveInterval(100.0d, 101.0d, 102.0d);
			trace.restoreProviderInputCost(1, restored);
			assertUnavailablePrice(restored, 17.0d);
		}
	}

	@Test
	void metadataKeepsUnknownResourceAxesUnderItsExplicitCallerFallbackPrice() {
		PackedCostEstimate declaration = unknownPriceDeclaration();
		PackedPhysicalMetadataArena arena = new PackedPhysicalMetadataArena(1);
		int metadata = arena.append(declaration, 17.0d, 31.0d);
		assertTrue(metadata > 0);
		PackedCostEstimate restored = new PackedCostEstimate();
		arena.restorePhysicalCost(metadata, restored);
		assertEquals(17.0d, restored.outputRows());
		assertTrue(Double.isNaN(restored.sequentialRows()));
		assertTrue(Double.isNaN(restored.resultRows()));
		assertEquals(2.0d, restored.randomSeeks());
		assertEquals(31.0d, restored.workRows(), "existing import uses the explicitly supplied caller price");
		assertEquals(31.0d, restored.objectivePoint());
	}

	private static PackedCostEstimate unknownPriceDeclaration() {
		PackedCostEstimate result = new PackedCostEstimate();
		result.setContextualRows(17.0d, 19.0d);
		result.setObjectiveInterval(2.0d, 3.0d, 5.0d);
		result.putPlannedDoubleMetric("producerMetric", 29.0d);
		result.setInclusivePhysicalCostPreservingUnknown(Double.NaN, 2.0d, 3.0d, 4.0d, 5.0d,
				6.0d, 7.0d, Double.NaN, 8.0d, 9.0d, Double.NaN);
		return result;
	}

	private static void assertUnavailablePrice(PackedCostEstimate estimate, double rows) {
		assertEquals(rows, estimate.outputRows());
		assertTrue(Double.isNaN(estimate.workRows()));
		assertTrue(Double.isNaN(estimate.sequentialRows()));
		assertTrue(Double.isNaN(estimate.resultRows()));
		assertEquals(2.0d, estimate.randomSeeks());
		assertEquals(8.0d, estimate.remoteCalls());
		assertFalse(estimate.hasObjectiveInterval());
		assertTrue(Double.isNaN(estimate.objectiveLower()));
		assertTrue(Double.isNaN(estimate.objectivePoint()));
		assertTrue(Double.isNaN(estimate.objectiveUpper()));
		assertFalse(estimate.plannedDoubleMetrics().containsKey("optimizer.objectiveLower"));
		assertFalse(estimate.plannedDoubleMetrics().containsKey("optimizer.objectivePoint"));
		assertFalse(estimate.plannedDoubleMetrics().containsKey("optimizer.objectiveUpper"));
	}

	private static final class BindingSession implements PackedCostSession {
		private final Set<Integer> produced = new HashSet<>();
		private int next;
		private int appendCalls;
		private final boolean recordingMissingOrigin;

		private BindingSession(int first) {
			this(first, false);
		}

		private BindingSession(int first, boolean recordingMissingOrigin) {
			next = first;
			this.recordingMissingOrigin = recordingMissingOrigin;
		}

		@Override
		public void estimateLeaf(int relation, PackedCostContext context, PackedCostEstimate output) {
			output.setRows(6.0d, 6.0d);
			attach(output);
		}

		@Override
		public void appendFactor(int relation, PackedCostContext context, PackedCostEstimate output) {
			appendCalls++;
			assertTrue(recordingMissingOrigin || produced.contains(context.evidenceStateId()),
					"only a prior current producer supplies the replay input");
			output.setContextualRows(context.prefixRows() / 2.0d, context.prefixRows() + 1.0d);
			attach(output);
		}

		@Override
		public void refineOperator(int relation, PackedCostContext context, PackedCostEstimate output) {
		}

		private void attach(PackedCostEstimate output) {
			output.setEvidenceStateId(++next);
			produced.add(next);
			output.setEvidenceGuarantee(EvidenceGuarantee.SCALAR_FALLBACK);
			output.setEvidenceDisposition(FrontierStateDisposition.BOUND_ONLY);
		}
	}
